import (
	"sync"
	"sync/atomic"
)

func FanIn(n int) int {
	var wg sync.WaitGroup
	var done atomic.Int64
	for i := 0; i < n; i++ {
		go func() {
			wg.Add(1)
			defer wg.Done()
			done.Add(1)
		}()
	}
	wg.Wait()
	return int(done.Load())
}

